            <text x="180" y="185" text-anchor="middle" font-size="11" fill="var(--text-secondary)">AND</text>

            <rect x="30" y="210" width="150" height="50" rx="8" fill="var(--surface)" stroke="var(--border)" stroke-width="1.5"/>
